SELECT ss.store_id, QUARTER(ss.sale_date) AS sale_quarter, ROUND(STDDEV(i.quantity), 2) AS stddev_quantity, AVG(i.quantity) AS avg_quantity FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY ss.store_id, QUARTER(ss.sale_date) HAVING stddev_quantity >= 35
